def selected(text):
    count = 0
    for character in text:
        if character == 'a':
            count = count + 1
    return len(text), count
print(selected('a😀a'))

def add(value, amount=2):
    return value + amount
print(add(3))

def character_count(text):
    return len(text)



SEPARATORS = " \t\n\r\v\f"


def metrics(text):
    if not isinstance(text, str):
        raise TypeError("text must be str")
    characters = character_count(text)
    words = 0
    lines = 0
    inside_word = False
    if text:
        lines = 1
    for character in text:
        if character == "\n":
            lines = lines + 1
        if character in SEPARATORS:
            inside_word = False
        elif not inside_word:
            words = words + 1
            inside_word = True
    return characters, words, lines

print(metrics(""))
print(metrics("A😀 é\nline two"))
